1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import {
4	  GAME_WIDTH,
5	  GAME_HEIGHT,
6	  GROUND_TOP_Y,
7	  HERO_X,
8	  MAX_HP,
9	  SCORE_SURVIVAL_PER_S,
10	  TARGET_DURATION_S,
11	} from '../config/gameConfig';
12	import { KEYS } from '../config/assetManifest';
13	import { t } from '../i18n/strings';
14	import { track, type FinishGameParams } from '../analytics/track';
15	import { createButton } from '../ui/Button';
16	import { HeroDog } from '../entities/HeroDog';
17	
18	/**
19	 * GameScene — Phase 1 PLACEHOLDER run screen. It renders the park backdrop, the
20	 * hero, and a HUD, fires `start_game` on entry, and exposes TEMPORARY debug
21	 * controls (on-screen Win/Lose buttons + W/L keys) that end the run, fire
22	 * `finish_game`, and hand a result to ResultsScene. No real gameplay/physics yet
23	 * — this exists purely to make the flow navigable end-to-end.
24	 */
25	export class GameScene extends Phaser.Scene {
26	  private hero!: HeroDog;
27	  private scoreText!: Phaser.GameObjects.Text;
28	  private progressFill!: Phaser.GameObjects.Rectangle;
29	
30	  private elapsedMs = 0;
31	  private score = 0;
32	  private finished = false;
33	
34	  constructor() {
35	    super({ key: SceneKey.Game });
36	  }
37	
38	  create(): void {
39	    this.elapsedMs = 0;
40	    this.score = 0;
41	    this.finished = false;
42	
43	    this.buildBackground();
44	    this.hero = new HeroDog(this, HERO_X, GROUND_TOP_Y);
45	    this.buildHud();
46	    // Jump zone BEFORE the debug buttons so the buttons sit on top (topOnly).
47	    this.buildJumpInput();
48	    this.buildDebugFinishControls();
49	
50	    // A round has begun.
51	    track('start_game');
52	
53	    // Keyboard jump (cosmetic hop only; real jump physics is Phase 2).
54	    const space = this.input.keyboard?.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);
55	    space?.on('down', () => this.hero.nudgeJump());
56	
57	    // Per-frame accumulator for active-play time (spec §7.2). Wired via the
58	    // scene UPDATE event so a later phase can freeze it during pause cleanly.
59	    this.events.on(Phaser.Scenes.Events.UPDATE, this.onUpdate, this);
60	    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
61	      this.events.off(Phaser.Scenes.Events.UPDATE, this.onUpdate, this);
62	    });
63	  }
64	
65	  private buildBackground(): void {
66	    const cx = GAME_WIDTH / 2;
67	    this.add.image(cx, GAME_HEIGHT / 2, KEYS.park_bg_far);
68	    this.add.image(cx, GROUND_TOP_Y, KEYS.park_bg_near).setOrigin(0.5, 1);
69	    this.add
70	      .tileSprite(cx, GROUND_TOP_Y, GAME_WIDTH, GAME_HEIGHT - GROUND_TOP_Y, KEYS.ground_tile)
71	      .setOrigin(0.5, 0);
72	    this.add.image(cx, GAME_HEIGHT, KEYS.park_fg_grass).setOrigin(0.5, 1);
73	  }
74	
75	  private buildHud(): void {
76	    // Level-progress bar: the FRAME is the `ui_progress_bar` asset (1180×14),
77	    // drawn FIRST; the dynamic fill rectangle is drawn ON TOP, inset within the
78	    // track bounds, so it's visible and animates as progress advances. Phase 2
79	    // swaps the SVG art against the same key/size — a transparent-window frame
80	    // still reads correctly with the fill sitting inside it. Fill logic unchanged.
81	    const barY = 16;
82	    const barW = 1180; // == ui_progress_bar asset width (see assetManifest)
83	    const barLeft = GAME_WIDTH / 2 - barW / 2;
84	    this.add.image(GAME_WIDTH / 2, barY, KEYS.ui_progress_bar); // frame (below)
85	    this.progressFill = this.add
86	      .rectangle(barLeft + 2, barY, barW - 4, 8, 0x6cc04a)
87	      .setOrigin(0, 0.5); // fill on top, inset within the track
88	    this.progressFill.scaleX = 0;
89	
90	    // Score row (top-left): the `ui_score_icon` asset next to the live score.
91	    const rowY = 58;
92	    this.add.image(38, rowY, KEYS.ui_score_icon);
93	    this.scoreText = this.add
94	      .text(68, rowY, `${t('hud_score')}: 0`, {
95	        fontFamily: 'system-ui, sans-serif',
96	        fontSize: '26px',
97	        fontStyle: 'bold',
98	        color: '#20272e',
99	      })
100	      .setOrigin(0, 0.5);
101	
102	    // Hearts (below the score row) — Phase 1 shows all full.
103	    for (let i = 0; i < MAX_HP; i++) {
104	      this.add.image(42 + i * 44, 100, KEYS.ui_heart_full);
105	    }
106	  }
107	
108	  /**
109	   * Jump input. Bound to a full-screen interactive Zone created BEFORE the debug
110	   * buttons, so with `input.topOnly` (Phaser default) a tap on a Win/Lose button
111	   * hits the button only — never also the jump. Real jump physics is Phase 2.
112	   */
113	  private buildJumpInput(): void {
114	    const jumpZone = this.add
115	      .zone(0, 0, GAME_WIDTH, GAME_HEIGHT)
116	      .setOrigin(0, 0)
117	      .setInteractive();
118	    jumpZone.on(Phaser.Input.Events.POINTER_DOWN, () => this.hero.nudgeJump());
119	  }
120	
121	  private buildDebugFinishControls(): void {
122	    this.add
123	      .text(GAME_WIDTH / 2, GAME_HEIGHT - 98, t('game_debug_hint'), {
124	        fontFamily: 'system-ui, sans-serif',
125	        fontSize: '16px',
126	        color: '#20272e',
127	      })
128	      .setOrigin(0.5);
129	
130	    createButton(this, {
131	      x: GAME_WIDTH / 2 - 135,
132	      y: GAME_HEIGHT - 50,
133	      width: 240,
134	      height: 56,
135	      label: t('game_debug_win'),
136	      onClick: () => this.finishRun('win'),
137	    });
138	    createButton(this, {
139	      x: GAME_WIDTH / 2 + 135,
140	      y: GAME_HEIGHT - 50,
141	      width: 240,
142	      height: 56,
143	      label: t('game_debug_lose'),
144	      onClick: () => this.finishRun('lose'),
145	    });
146	
147	    const kb = this.input.keyboard;
148	    kb?.addKey(Phaser.Input.Keyboard.KeyCodes.W).on('down', () => this.finishRun('win'));
149	    kb?.addKey(Phaser.Input.Keyboard.KeyCodes.L).on('down', () => this.finishRun('lose'));
150	  }
151	
152	  private onUpdate(_time: number, delta: number): void {
153	    if (this.finished) return;
154	
155	    this.elapsedMs += delta;
156	    const seconds = this.elapsedMs / 1000;
157	
158	    this.score = Math.floor(seconds * SCORE_SURVIVAL_PER_S);
159	    this.scoreText.setText(`${t('hud_score')}: ${this.score}`);
160	
161	    const progress = Phaser.Math.Clamp(seconds / TARGET_DURATION_S.nominal, 0, 1);
162	    this.progressFill.scaleX = progress;
163	  }
164	
165	  private finishRun(result: 'win' | 'lose'): void {
166	    if (this.finished) return;
167	    this.finished = true;
168	
169	    const payload: FinishGameParams = {
170	      result,
171	      score: this.score,
172	      duration_s: Math.round(this.elapsedMs / 1000),
173	    };
174	    track('finish_game', payload);
175	    this.scene.start(SceneKey.Results, payload);
176	  }
177	}
